const CSS_BASE = `
  * { box-sizing: border-box; margin: 0; padding: 0; }
  body { font-family: Arial, sans-serif; color: #000; background: #fff; }
  table { border-collapse: collapse; }
  p { margin: 0; padding: 0; }
`

// ═══════════════════════════════════════════════════════════════════════
// buildBody — genera HTML exacto al formato Word para cada tipo
// ═══════════════════════════════════════════════════════════════════════
export function buildBody(f, actividad, versionFirma) {
  if (actividad === 'Contraste' || actividad === 'Contrastes') return buildContrastes(f, versionFirma)
  if (actividad === 'Avisos')    return buildAvisos(f, versionFirma)
  if (actividad === 'Reemplazo') return buildReemplazo(f, versionFirma)
  // Generic fallback
  const c = getCfg(actividad)
  return buildGenerico(f, c, versionFirma)
}

