// ═══════════════════════════════════════════════════════════════════════
// generarHTMLDoc — PDF individual
// ═══════════════════════════════════════════════════════════════════════
export function generarHTMLDoc(f, actividad, versionFirma) {
  const body = buildBody(f, actividad, versionFirma)
  // Margins from exact Word measurements (in mm)
  const isAvisos = actividad === 'Avisos'
  const isContrastes = actividad === 'Contraste' || actividad === 'Contrastes'
  const mT = isAvisos ? 20.21 : 16.23
  const mB = 25.40
  const mL = isAvisos ? 18.50 : (actividad === 'Reemplazo' ? 13.97 : 11.73)
  const mR = isAvisos ? 19.35 : (actividad === 'Reemplazo' ? 13.95 : 13.71)

  return `<!DOCTYPE html><html lang="es"><head><meta charset="UTF-8">
<style>
@page { size: 279.4mm 215.9mm landscape; margin: ${mT}mm ${mR}mm ${mB}mm ${mL}mm; }
${CSS_BASE}
body { font-size: 9pt; }
</style></head><body>
${body}
<script>window.addEventListener('load',function(){setTimeout(function(){window.print()},400)})<\/script>
</body></html>`
}

// ═══════════════════════════════════════════════════════════════════════
// generarHTMLLote — PDF en bloque (múltiples OTs)
// ═══════════════════════════════════════════════════════════════════════
export function generarHTMLLote(forms, actividades, versionFirma) {
  const pages = forms.map(function(f, i) {
    const body = buildBody(f, actividades[i], versionFirma)
    const pb = i < forms.length - 1 ? 'page-break-after:always' : ''
    return '<div style="' + pb + '">' + body + '</div>'
  }).join('\n')
  return `<!DOCTYPE html><html lang="es"><head><meta charset="UTF-8">
<style>
@page { size: 279.4mm 215.9mm landscape; margin: 16mm 14mm 25mm 12mm; }
${CSS_BASE}
body { font-size: 9pt; }
</style></head><body>
${pages}
<script>window.addEventListener('load',function(){setTimeout(function(){window.print()},600)})<\/script>
</body></html>`
}

export function imprimirDoc(f, actividad, versionFirma) {
  window.open(URL.createObjectURL(new Blob([generarHTMLDoc(f, actividad, versionFirma)], { type: 'text/html' })), '_blank')
}

// ═══════════════════════════════════════════════════════════════════════
// descargarWord — Word compatible
// Usa HTML-Word con MSO namespace, sin floats
// ═══════════════════════════════════════════════════════════════════════
export function descargarWord(f, actividad, versionFirma) {
  const isAvisos = actividad === 'Avisos'
  const isReemplazo = actividad === 'Reemplazo'
  const mT = isAvisos ? 20.21 : 16.23
  const mB = 25.40
  const mL = isAvisos ? 18.50 : (isReemplazo ? 13.97 : 11.73)
  const mR = isAvisos ? 19.35 : (isReemplazo ? 13.95 : 13.71)
  const body = buildBody(f, actividad, versionFirma)
  const titulo = f.titulo || actividad || 'OT'

  const html = `<!DOCTYPE html>
<html xmlns:o="urn:schemas-microsoft-com:office:office"
      xmlns:w="urn:schemas-microsoft-com:office:word"
      xmlns="http://www.w3.org/TR/REC-html40">
<head><meta charset="UTF-8"><title>${titulo}</title>
<!--[if gte mso 9]><xml>
<w:WordDocument><w:View>Print</w:View><w:Zoom>100</w:Zoom><w:DoNotOptimizeForBrowser/></w:WordDocument>
<o:OfficeDocumentSettings><o:PixelsPerInch>96</o:PixelsPerInch></o:OfficeDocumentSettings>
</xml><![endif]-->
<style>
@page WordSection1 {
  size:279.4mm 215.9mm; mso-page-orientation:landscape;
  margin:${mT}mm ${mR}mm ${mB}mm ${mL}mm;
}
div.Section1 { page:WordSection1; }
${CSS_BASE}
body { font-size:9pt; }
</style></head>
<body><div class="Section1">${body}</div></body></html>`

  const blob = new Blob([html], { type: 'application/vnd.ms-word;charset=utf-8' })
  const url = URL.createObjectURL(blob)
  const a = document.createElement('a')
  a.href = url
  a.download = 'OT_' + (f.codigo_ot || f.numero_ot) + '_' + (actividad || 'doc') + '.doc'
  document.body.appendChild(a); a.click(); document.body.removeChild(a)
  setTimeout(function() { URL.revokeObjectURL(url) }, 1500)
}